import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const ThongTinCaNhan = () => {
    const navigate = useNavigate();

    // --- CẤU TRÚC DỮ LIỆU CHUẨN BACKEND ---
    const [profile, setProfile] = useState({
        room_id: '',   // Dùng room_id thay vì chỉ 'room' để sau này map với bảng Rooms trong DB
        full_name: '',
        phone_number: '',
        is_verified: false
    });

    const [loading, setLoading] = useState(true);
    const [isEditing, setIsEditing] = useState(false);
    const [errors, setErrors] = useState({});

    // 1. LẤY DỮ LIỆU (GET API)
    useEffect(() => {
        const loadInitialData = async () => {
            setLoading(true);
            try {
                // SAU NÀY: const res = await axios.get('/api/user/profile');
                // HIỆN TẠI: Lấy từ localStorage
                const saved = localStorage.getItem('userProfile');
                if (saved) {
                    setProfile(JSON.parse(saved));
                }
            } catch (err) {
                console.error("Lỗi lấy dữ liệu:", err);
            } finally {
                setLoading(false);
            }
        };
        loadInitialData();
    }, []);

    // 2. KIỂM TRA DỮ LIỆU (VALIDATION)
    const validate = () => {
        let tempErrors = {};
        if (!profile.room_id) tempErrors.room = "Vui lòng chọn phòng";
        if (!profile.full_name.trim()) tempErrors.name = "Tên không được để trống";
        if (!/^0\d{9}$/.test(profile.phone_number)) {
            tempErrors.phone = "SĐT phải bắt đầu bằng 0 và đủ 10 số";
        }
        setErrors(tempErrors);
        return Object.keys(tempErrors).length === 0;
    };

    // 3. CẬP NHẬT DỮ LIỆU (POST/PUT API)
    const handleUpdate = async () => {
        if (!validate()) return;

        try {
            // SAU NÀY: await axios.post('/api/user/update-profile', profile);

            // HIỆN TẠI: Giả lập lưu thành công
            const updatedProfile = { ...profile, is_verified: true };
            localStorage.setItem('userProfile', JSON.stringify(updatedProfile));
            localStorage.setItem('isProfileUpdated', 'true');

            setProfile(updatedProfile);
            setIsEditing(false);
            alert("Cập nhật dữ liệu hệ thống thành công!");
            navigate('/dashboard-cu-dan/thong-bao');
        } catch (err) {
            alert("Lỗi kết nối Server!");
        }
    };

    if (loading) return <div style={centerStyle}>Đang tải dữ liệu...</div>;

    return (
        <div style={containerStyle} className="glass-card">
            <div style={headerStyle}>
                <h2 style={{ color: '#fff', margin: 0, fontSize: '18px' }}>👤 THÔNG TIN TÀI KHOẢN</h2>
            </div>

            <div style={contentWrapperStyle}>
                <div style={mainContentStyle}>
                    {(!profile.is_verified || isEditing) ? (
                        <div style={{ animation: 'fadeIn 0.3s' }}>
                            <h3 style={titleStyle}>CẬP NHẬT THÔNG TIN HỆ THỐNG</h3>

                            <div style={inputGroup}>
                                <label style={labelStyle}>Mã căn hộ: {errors.room && <span style={errorLabel}>{errors.room}</span>}</label>
                                <select 
                                    style={selectStyle}
                                    value={profile.room_id}
                                    onChange={(e) => setProfile({...profile, room_id: e.target.value})}
                                >
                                    <option value="">-- Chọn phòng --</option>
                                    {[...Array(9)].map((_, f) => (
                                        [1,2,3,4,5].map(r => (
                                            <option key={`${f+1}0${r}`} value={`${f+1}0${r}`}>{`${f+1}0${r}`}</option>
                                        ))
                                    ))}
                                </select>
                            </div>

                            <div style={inputGroup}>
                                <label style={labelStyle}>Họ và tên cư dân: {errors.name && <span style={errorLabel}>{errors.name}</span>}</label>
                                <input 
                                    style={inputStyle}
                                    value={profile.full_name}
                                    onChange={(e) => setProfile({...profile, full_name: e.target.value})}
                                />
                            </div>

                            <div style={inputGroup}>
                                <label style={labelStyle}>Số điện thoại: {errors.phone && <span style={errorLabel}>{errors.phone}</span>}</label>
                                <input 
                                    style={{...inputStyle, borderColor: errors.phone ? 'red' : '#ddd'}}
                                    value={profile.phone_number}
                                    onChange={(e) => setProfile({...profile, phone_number: e.target.value})}
                                />
                            </div>

                            <button onClick={handleUpdate} style={btnSaveStyle}>XÁC NHẬN LƯU DỮ LIỆU</button>
                        </div>
                    ) : (
                        <div style={{ animation: 'fadeIn 0.3s', textAlign: 'center' }}>
                            <div style={avatarCircle}>{profile.full_name.charAt(0).toUpperCase()}</div>
                            <h2 style={{ fontSize: '28px', margin: '5px 0' }}>{profile.full_name}</h2>
                            <p style={{ color: '#8b5e5e', fontWeight: 'bold' }}>Căn hộ: {profile.room_id}</p>

                            <div style={displayInfoBox}>
                                <div style={infoRow}>
                                    <span>Liên hệ:</span>
                                    <strong>{profile.phone_number}</strong>
                                </div>
                                <div style={infoRow}>
                                    <span>Định danh:</span>
                                    <span style={{ color: '#28a745' }}>✓ Đã đồng bộ Backend</span>
                                </div>
                            </div>

                            <button onClick={() => setIsEditing(true)} style={btnEditStyle}>
                                CHỈNH SỬA THÔNG TIN
                            </button>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

// --- STYLES TỐI ƯU ---
const containerStyle = { flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover', height: 'calc(100vh - 120px)', overflow: 'hidden' };
const headerStyle = { padding: '15px 25px', background: 'rgba(0,0,0,0.2)' };
const contentWrapperStyle = { flex: 1, padding: '20px', display: 'flex', justifyContent: 'center', alignItems: 'center' };
const mainContentStyle = { width: '100%', maxWidth: '500px', backgroundColor: '#fff', borderRadius: '25px', padding: '30px', boxShadow: '0 10px 25px rgba(0,0,0,0.1)' };
const titleStyle = { color: '#8b5e5e', fontSize: '18px', marginBottom: '25px', textAlign: 'center', fontWeight: 'bold' };
const labelStyle = { display: 'flex', justifyContent: 'space-between', fontWeight: 'bold', marginBottom: '8px', color: '#555', fontSize: '13px' };
const errorLabel = { color: 'red', fontSize: '11px' };
const inputGroup = { marginBottom: '15px' };
const inputStyle = { width: '100%', padding: '10px 15px', borderRadius: '10px', border: '1px solid #ddd', fontSize: '15px', outline: 'none', boxSizing: 'border-box' };
const selectStyle = { ...inputStyle, cursor: 'pointer', appearance: 'none', background: '#f9f9f9' };
const btnSaveStyle = { width: '100%', padding: '12px', borderRadius: '12px', border: 'none', backgroundColor: '#8b5e5e', color: '#fff', fontWeight: 'bold', cursor: 'pointer', marginTop: '10px' };
const avatarCircle = { width: '70px', height: '70px', borderRadius: '50%', backgroundColor: '#8b5e5e', color: '#fff', fontSize: '28px', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 15px', fontWeight: 'bold' };
const displayInfoBox = { background: '#fcfcfc', border: '1px solid #f0f0f0', borderRadius: '15px', padding: '15px 25px', margin: '20px 0' };
const infoRow = { display: 'flex', justifyContent: 'space-between', padding: '8px 0', fontSize: '14px' };
const btnEditStyle = { padding: '8px 20px', borderRadius: '10px', border: '1px solid #8b5e5e', backgroundColor: 'transparent', color: '#8b5e5e', fontWeight: 'bold', cursor: 'pointer', fontSize: '13px' };
const centerStyle = { display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh', color: '#fff' };

export default ThongTinCaNhan;
